const CC_ICON_CREDIT = 'Card emblems: game-icons.net by Lorc, Delapouite and contributors (CC BY 3.0).';

/* one palette per playstyle: art background (top → bottom), glow, and the emblem's metal (light → deep) */
const CC_PAL = {
  aggression: { a: '#4a1018', b: '#12050a', g: '#ff6a4d', e: ['#fff6ef', '#ffc2a0', '#ff7a55', '#a8231a'] },
  defense: { a: '#0f2850', b: '#050b1a', g: '#5fb4ff', e: ['#f6fbff', '#c4e2ff', '#6fb0ff', '#1f4fa8'] },
  control: { a: '#2c1352', b: '#0b0518', g: '#b886ff', e: ['#fcf6ff', '#e0c8ff', '#a876ff', '#5523b0'] },
  mobility: { a: '#0c3a31', b: '#03110e', g: '#3fe2b0', e: ['#f2fffa', '#b8f5e0', '#4fdcb0', '#11795c'] },
  support: { a: '#40300c', b: '#130d03', g: '#ffcf5e', e: ['#fffbee', '#ffe7a6', '#ffc552', '#9a6612'] }
};
/* the shared <defs>: emblem metals per playstyle plus gold, silver and crystal (referenced as url(#…)) */
function ccDefs() {
  if (document.getElementById('ccDefs')) return;
  const g = (id, stops, x2 = 0, y2 = 1) => `<linearGradient id="${id}" x1="0" y1="0" x2="${x2}" y2="${y2}">${stops.map((c, i) => `<stop offset="${(i / (stops.length - 1)).toFixed(2)}" stop-color="${c}"/>`).join('')}</linearGradient>`;
  const s = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  s.id = 'ccDefs'; s.setAttribute('width', '0'); s.setAttribute('height', '0'); s.setAttribute('aria-hidden', 'true');
  s.style.cssText = 'position:absolute;width:0;height:0;overflow:hidden;pointer-events:none';
  s.innerHTML = '<defs>' + Object.entries(CC_PAL).map(([k, p]) => g('ccgE-' + k, p.e)).join('') +
    g('ccgGold', ['#fff4cf', '#f1cf7d', '#b8873a', '#e9c679', '#7c5420'], .4, 1) + g('ccgSilver', ['#ffffff', '#dfe5ef', '#8f98aa', '#e8edf5', '#5d6577'], .4, 1) +
    g('ccgCrystal', ['#ffffff', '#ffd9f4', '#c9a6ff', '#8fb8ff']) + g('ccgBlood', ['#ffe0e0', '#ff6b6b', '#a3101f']) + '</defs>';
  document.body.appendChild(s);
}
const ccIco = (key, cls = '') => `<svg viewBox="0 0 512 512" class="cci ${cls}" aria-hidden="true"><path d="${CC_ICO[key] || ''}"/></svg>`;
/* the back of a card (the bot's hand, face-down traps, the draw piles) */
const ccBackHTML = (cls = '') => `<span class="ccbk ${cls}"><i class="ccbk-ring"></i>${ccIco('crystal', 'ccbk-em')}</span>`;
/* nothing heavy to prepare any more: the board is CSS, so this only makes sure the gradients exist */
function ccArtPrewarm() { ccDefs(); }
